import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    environment: 'node',
    include: ['test/**/*.test.ts'],
  },
});

import { ConfigError, loadConfig, SERVICE_NAME, type Config } from './config.js';
import { createLogger } from './logger.js';
import { createServer } from './server.js';

function errorMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

function loadOrReport(): Config | undefined {
  try {
    return loadConfig(process.env);
  } catch (err) {
    const message = err instanceof ConfigError ? err.message : errorMessage(err);
    createLogger({ service: SERVICE_NAME, level: 'info' }).error('invalid configuration', { error: message });
    return undefined;
  }
}

async function main(): Promise<void> {
  const config = loadOrReport();
  if (config === undefined) {
    process.exitCode = 1;
    return;
  }

  const logger = createLogger({ service: SERVICE_NAME, level: config.logLevel });
  const server = createServer({ config, logger });

  try {
    await server.start();
  } catch (err) {
    logger.error('failed to start server', { error: errorMessage(err) });
    process.exitCode = 1;
    return;
  }

  let stopping: Promise<void> | undefined;
  const onSignal = (signal: NodeJS.Signals): void => {
    if (stopping !== undefined) {
      logger.debug('signal ignored, shutdown already in progress', { signal });
      return;
    }
    logger.info('signal received', { signal });
    stopping = server.shutdown().then(({ forced }) => {
      if (forced) process.exitCode = 1;
    });
  };
  process.on('SIGTERM', onSignal);
  process.on('SIGINT', onSignal);
}

main().catch((err: unknown) => {
  createLogger({ service: SERVICE_NAME, level: 'error' }).error('fatal', { error: errorMessage(err) });
  process.exitCode = 1;
});

import { randomUUID } from 'node:crypto';
import { createServer as createHttpServer, type IncomingMessage, type Server, type ServerResponse } from 'node:http';
import { readJsonBody } from './body.js';
import type { Config } from './config.js';
import { HttpError, toErrorResponse } from './errors.js';
import { withFields } from './logger.js';
import { parseQuery, Router } from './router.js';
import { registerHealthRoutes } from './routes/health.js';
{{#if exampleResource}}
import { registerItemRoutes } from './routes/items.js';
{{/if}}
{{#if cors}}
import { createCorsMiddleware } from './middleware/cors.js';
{{/if}}
import { Reply, type Context, type Logger, type Middleware } from './types.js';

export interface ServerOptions {
  config: Config;
  logger: Logger;
  /** Adds routes after the built-in ones. Used by tests and by code that embeds the server. */
  register?: (router: Router) => void;
}

export interface StartResult {
  host: string;
  port: number;
}

export interface ShutdownResult {
  /** True when requests were still running at the timeout and their connections were destroyed. */
  forced: boolean;
}

export interface AppServer {
  /** Listens on config.host and config.port. Port 0 picks a free port. */
  start(): Promise<StartResult>;
  /** Stops accepting connections and drains in-flight requests. Safe to call more than once. */
  shutdown(): Promise<ShutdownResult>;
  /** True while listening and not shutting down. */
  isReady(): boolean;
}

type State = 'idle' | 'listening' | 'stopping' | 'stopped';

const REQUEST_ID_PATTERN = /^[\x21-\x7e]{1,200}$/;

function requestIdFrom(header: string | string[] | undefined): string {
  if (typeof header === 'string' && REQUEST_ID_PATTERN.test(header)) return header;
  return randomUUID();
}

function isQuietPath(pathname: string): boolean {
  return pathname === '/health' || pathname === '/ready';
}

function writeJson(res: ServerResponse, status: number, body: unknown): void {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function sendResult(res: ServerResponse, result: unknown): void {
  if (res.headersSent || res.writableEnded) return; // the handler wrote the response itself
  if (result === undefined) {
    res.statusCode = 204;
    res.end();
    return;
  }
  if (result instanceof Reply) {
    for (const [name, value] of Object.entries(result.headers)) res.setHeader(name, value);
    if (result.body === undefined) {
      res.statusCode = result.status;
      res.end();
      return;
    }
    writeJson(res, result.status, result.body);
    return;
  }
  writeJson(res, 200, result);
}

function sendError(ctx: Context, err: unknown): void {
  const { res } = ctx;
  const response = toErrorResponse(err);
  if (response.unexpected) {
    ctx.log.error('unhandled error', {
      error: err instanceof Error ? err.message : String(err),
      stack: err instanceof Error ? err.stack : undefined,
    });
  }
  if (res.headersSent) {
    res.destroy(); // a JSON error cannot be sent once headers are out
    return;
  }
  for (const [name, value] of Object.entries(response.headers)) res.setHeader(name, value);
  writeJson(res, response.status, response.body);
}

export function createServer(options: ServerOptions): AppServer {
  const { config, logger } = options;
  let state: State = 'idle';
  let shutdownResult: Promise<ShutdownResult> | undefined;

  const router = new Router();
  registerHealthRoutes(router, () => state === 'listening');
{{#if exampleResource}}
  registerItemRoutes(router);
{{/if}}
  options.register?.(router);

  const middlewares: Middleware[] = [];
{{#if cors}}
  middlewares.push(createCorsMiddleware(config.corsOrigin));
{{/if}}

  /** Once shutdown has started, every response closes its connection so keep-alive sockets drain. */
  function closeAfterResponse(res: ServerResponse): void {
    if (state !== 'listening') res.setHeader('connection', 'close');
  }

  async function runMiddlewares(ctx: Context, index: number, last: () => Promise<void>): Promise<void> {
    const middleware = middlewares[index];
    if (middleware === undefined) {
      await last();
      return;
    }
    await middleware(ctx, () => runMiddlewares(ctx, index + 1, last));
  }

  async function dispatch(ctx: Context, pathname: string): Promise<void> {
    const method = (ctx.req.method ?? 'GET').toUpperCase();
    const resolution = router.resolve(method, pathname);
    if (resolution.kind === 'not-found') {
      throw new HttpError(404, 'not_found', `No route matches ${pathname}`);
    }
    if (resolution.kind === 'method-not-allowed') {
      throw new HttpError(405, 'method_not_allowed', `${method} is not allowed on ${pathname}`, {
        allow: resolution.allow.join(', '),
      });
    }

    ctx.params = resolution.params;
    if (method === 'POST' || method === 'PUT' || method === 'PATCH') {
      ctx.body = await readJsonBody(ctx.req, config.bodyLimitBytes);
    }
    const result = await resolution.handler(ctx);
    // Checked after the handler runs: a request that finishes during shutdown must not keep its socket alive.
    closeAfterResponse(ctx.res);
    sendResult(ctx.res, result);
  }

  async function handleRequest(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const startedAt = process.hrtime.bigint();
    const requestId = requestIdFrom(req.headers['x-request-id']);
    const method = (req.method ?? 'GET').toUpperCase();
    // The prefix keeps `//path` from being parsed as a host name.
    const url = new URL(req.url?.startsWith('/') ? `http://localhost${req.url}` : 'http://localhost/');

    res.setHeader('x-request-id', requestId);
    closeAfterResponse(res);
    res.once('finish', () => {
      const durationMs = Number(process.hrtime.bigint() - startedAt) / 1e6;
      const fields = {
        method,
        path: url.pathname,
        status: res.statusCode,
        durationMs: Math.round(durationMs * 1000) / 1000,
        requestId,
      };
      if (isQuietPath(url.pathname)) logger.debug('request completed', fields);
      else logger.info('request completed', fields);
    });

    const ctx: Context = {
      req,
      res,
      params: Object.create(null) as Record<string, string>,
      query: parseQuery(url.searchParams),
      body: undefined,
      log: withFields(logger, { requestId }),
      requestId,
    };
    try {
      await runMiddlewares(ctx, 0, () => dispatch(ctx, url.pathname));
    } catch (err) {
      closeAfterResponse(res);
      sendError(ctx, err);
    }
  }

  const server: Server = createHttpServer((req, res) => {
    handleRequest(req, res).catch((err: unknown) => {
      logger.error('request handling failed', { error: err instanceof Error ? err.message : String(err) });
      res.destroy();
    });
  });

  function start(): Promise<StartResult> {
    if (state !== 'idle') return Promise.reject(new Error(`Cannot start a server that is ${state}`));
    return new Promise<StartResult>((resolve, reject) => {
      const onError = (err: Error): void => reject(err);
      server.once('error', onError);
      server.listen(config.port, config.host, () => {
        server.off('error', onError);
        state = 'listening';
        const address = server.address();
        const port = typeof address === 'object' && address !== null ? address.port : config.port;
        logger.info('server listening', { host: config.host, port });
        resolve({ host: config.host, port });
      });
    });
  }

  async function drain(): Promise<ShutdownResult> {
    const closed = new Promise<void>((resolve) => {
      server.close(() => resolve());
    });
    server.closeIdleConnections();

    let forced = false;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const deadline = new Promise<void>((resolve) => {
      timer = setTimeout(() => {
        forced = true;
        logger.warn('shutdown timeout reached, destroying remaining connections', {
          timeoutMs: config.shutdownTimeoutMs,
        });
        server.closeAllConnections();
        resolve();
      }, config.shutdownTimeoutMs);
    });

    await Promise.race([closed, deadline]);
    clearTimeout(timer);
    await closed;
    state = 'stopped';
    logger.info('shutdown complete', { forced });
    return { forced };
  }

  function shutdown(): Promise<ShutdownResult> {
    if (shutdownResult === undefined) {
      state = 'stopping';
      logger.info('shutdown started', { timeoutMs: config.shutdownTimeoutMs });
      shutdownResult = drain();
    }
    return shutdownResult;
  }

  return { start, shutdown, isReady: () => state === 'listening' };
}

import { parseLogLevel, type LogLevel } from './logger.js';

export const SERVICE_NAME = '{{{projectName}}}';

const DEFAULT_PORT = {{{port}}};
const DEFAULT_HOST = '0.0.0.0';
const DEFAULT_SHUTDOWN_TIMEOUT_MS = 10000;
const DEFAULT_BODY_LIMIT_BYTES = 1048576;

export class ConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ConfigError';
  }
}

export interface Config {
  port: number;
  host: string;
  logLevel: LogLevel;
  shutdownTimeoutMs: number;
  bodyLimitBytes: number;
{{#if cors}}
  corsOrigin: string;
{{/if}}
}

function readInteger(env: NodeJS.ProcessEnv, name: string, fallback: number, min: number, max: number): number {
  const raw = env[name]?.trim();
  if (raw === undefined || raw === '') return fallback;
  if (!/^\d+$/.test(raw)) throw new ConfigError(`${name} must be an integer, got "${raw}"`);
  const value = Number(raw);
  if (value < min || value > max) throw new ConfigError(`${name} must be between ${min} and ${max}, got ${raw}`);
  return value;
}

/** Reads configuration from environment variables. Throws ConfigError on an invalid numeric value. */
export function loadConfig(env: NodeJS.ProcessEnv = process.env): Config {
  return {
    port: readInteger(env, 'PORT', DEFAULT_PORT, 1, 65535),
    host: env.HOST?.trim() || DEFAULT_HOST,
    logLevel: parseLogLevel(env.LOG_LEVEL),
    shutdownTimeoutMs: readInteger(env, 'SHUTDOWN_TIMEOUT_MS', DEFAULT_SHUTDOWN_TIMEOUT_MS, 0, 3600000),
    bodyLimitBytes: readInteger(env, 'BODY_LIMIT_BYTES', DEFAULT_BODY_LIMIT_BYTES, 1, 1073741824),
{{#if cors}}
    corsOrigin: env.CORS_ORIGIN?.trim() || '*',
{{/if}}
  };
}

import type { Logger } from './types.js';

export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

export type LogSink = (line: string) => void;

const RANK: Record<LogLevel, number> = { debug: 10, info: 20, warn: 30, error: 40 };

/** Parses LOG_LEVEL. Unknown or missing values fall back to `info`. */
export function parseLogLevel(value: string | undefined): LogLevel {
  const normalized = value?.trim().toLowerCase();
  if (normalized === 'debug' || normalized === 'info' || normalized === 'warn' || normalized === 'error') {
    return normalized;
  }
  return 'info';
}

export interface LoggerOptions {
  service: string;
  level?: LogLevel;
  /** Receives each formatted line. Defaults to stdout. */
  sink?: LogSink;
  now?: () => Date;
}

const stdoutSink: LogSink = (line) => {
  process.stdout.write(`${line}\n`);
};

export function createLogger(options: LoggerOptions): Logger {
  const threshold = RANK[options.level ?? 'info'];
  const sink = options.sink ?? stdoutSink;
  const now = options.now ?? (() => new Date());

  const write = (level: LogLevel, msg: string, fields: Record<string, unknown> = {}): void => {
    if (RANK[level] < threshold) return;
    const entry: Record<string, unknown> = { time: now().toISOString(), level, msg, service: options.service };
    // Caller fields may add keys but never overwrite time, level, msg or service.
    for (const [key, value] of Object.entries(fields)) {
      if (!(key in entry)) entry[key] = value;
    }
    sink(JSON.stringify(entry));
  };

  return {
    debug: (msg, fields) => write('debug', msg, fields),
    info: (msg, fields) => write('info', msg, fields),
    warn: (msg, fields) => write('warn', msg, fields),
    error: (msg, fields) => write('error', msg, fields),
  };
}

/** Returns a logger that adds `fields` to every line it writes. */
export function withFields(logger: Logger, fields: Record<string, unknown>): Logger {
  return {
    debug: (msg, extra) => logger.debug(msg, { ...fields, ...extra }),
    info: (msg, extra) => logger.info(msg, { ...fields, ...extra }),
    warn: (msg, extra) => logger.warn(msg, { ...fields, ...extra }),
    error: (msg, extra) => logger.error(msg, { ...fields, ...extra }),
  };
}

import { HttpError } from './errors.js';
import type { Handler, Query } from './types.js';

export type Method = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';

type Segment = { kind: 'static'; value: string } | { kind: 'param'; name: string };

interface Route {
  method: Method;
  pattern: string;
  segments: Segment[];
  handler: Handler;
}

export type Resolution =
  | { kind: 'found'; handler: Handler; params: Record<string, string> }
  | { kind: 'method-not-allowed'; allow: Method[] }
  | { kind: 'not-found' };

/** Splits a path on `/`. Empty segments are dropped, so a trailing slash is ignored. */
function splitPath(path: string): string[] {
  return path.split('/').filter((part) => part.length > 0);
}

function parsePattern(pattern: string): Segment[] {
  if (!pattern.startsWith('/')) throw new Error(`Route pattern must start with "/": ${pattern}`);
  return splitPath(pattern).map((part): Segment => {
    if (!part.startsWith(':')) return { kind: 'static', value: part };
    const name = part.slice(1);
    if (name.length === 0) throw new Error(`Route pattern "${pattern}" has an unnamed parameter`);
    return { kind: 'param', name };
  });
}

/** Orders routes most specific first: a static segment beats a parameter segment at the same position. */
function compareSpecificity(a: Route, b: Route): number {
  for (let i = 0; i < a.segments.length; i += 1) {
    const left = a.segments[i]?.kind === 'static' ? 0 : 1;
    const right = b.segments[i]?.kind === 'static' ? 0 : 1;
    if (left !== right) return left - right;
  }
  return 0;
}

function matchesShape(segments: Segment[], parts: string[]): boolean {
  if (segments.length !== parts.length) return false;
  return segments.every((segment, i) => segment.kind === 'param' || segment.value === parts[i]);
}

function decodeSegment(raw: string): string {
  try {
    return decodeURIComponent(raw);
  } catch {
    throw new HttpError(400, 'bad_request', 'Malformed percent-encoding in path');
  }
}

function extractParams(segments: Segment[], parts: string[]): Record<string, string> {
  const params = Object.create(null) as Record<string, string>;
  segments.forEach((segment, i) => {
    if (segment.kind === 'param') params[segment.name] = decodeSegment(parts[i] ?? '');
  });
  return params;
}

/** Method and `:param` router. Static segments take precedence over parameter segments. */
export class Router {
  readonly #routes: Route[] = [];

  get(pattern: string, handler: Handler): this {
    return this.add('GET', pattern, handler);
  }

  post(pattern: string, handler: Handler): this {
    return this.add('POST', pattern, handler);
  }

  put(pattern: string, handler: Handler): this {
    return this.add('PUT', pattern, handler);
  }

  patch(pattern: string, handler: Handler): this {
    return this.add('PATCH', pattern, handler);
  }

  delete(pattern: string, handler: Handler): this {
    return this.add('DELETE', pattern, handler);
  }

  add(method: Method, pattern: string, handler: Handler): this {
    const segments = parsePattern(pattern);
    if (this.#routes.some((route) => route.method === method && route.pattern === pattern)) {
      throw new Error(`Duplicate route ${method} ${pattern}`);
    }
    this.#routes.push({ method, pattern, segments, handler });
    return this;
  }

  resolve(method: string, pathname: string): Resolution {
    const parts = splitPath(pathname);
    const candidates = this.#routes
      .filter((route) => matchesShape(route.segments, parts))
      .sort(compareSpecificity);
    if (candidates.length === 0) return { kind: 'not-found' };

    const upper = method.toUpperCase();
    const chosen = candidates.find((route) => route.method === upper);
    if (chosen === undefined) {
      const allow = [...new Set(candidates.map((route) => route.method))].sort();
      return { kind: 'method-not-allowed', allow };
    }
    return { kind: 'found', handler: chosen.handler, params: extractParams(chosen.segments, parts) };
  }
}

/** Parses a query string. A key that repeats becomes an array of its values. */
export function parseQuery(params: URLSearchParams): Query {
  const query = Object.create(null) as Query;
  for (const key of new Set(params.keys())) {
    const values = params.getAll(key);
    query[key] = values.length === 1 ? (values[0] ?? '') : values;
  }
  return query;
}

import type { IncomingMessage } from 'node:http';
import { HttpError } from './errors.js';

/** True for `application/json`, ignoring parameters such as `charset`. */
export function isJsonContentType(header: string | undefined): boolean {
  if (header === undefined) return false;
  const mediaType = header.split(';')[0]?.trim().toLowerCase();
  return mediaType === 'application/json';
}

/**
 * Reads the request body but never buffers more than `limit` bytes. Past the
 * limit the stream is paused and the request is rejected with 413.
 */
function readRawBody(req: IncomingMessage, limit: number): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let received = 0;

    const onData = (chunk: Buffer): void => {
      received += chunk.length;
      if (received > limit) {
        req.off('data', onData);
        req.pause();
        reject(new HttpError(413, 'payload_too_large', `Request body exceeds ${limit} bytes`, { connection: 'close' }));
        return;
      }
      chunks.push(chunk);
    };

    req.on('data', onData);
    req.on('end', () => resolve(Buffer.concat(chunks)));
    req.on('error', reject);
  });
}

/**
 * Parses the JSON body of a POST, PUT or PATCH request. An empty body yields
 * `undefined`. A non-empty body must have an application/json content type.
 */
export async function readJsonBody(req: IncomingMessage, limit: number): Promise<unknown> {
  const raw = await readRawBody(req, limit);
  if (raw.length === 0) return undefined;
  if (!isJsonContentType(req.headers['content-type'])) {
    throw new HttpError(415, 'unsupported_media_type', 'Content-Type must be application/json');
  }
  try {
    return JSON.parse(raw.toString('utf8')) as unknown;
  } catch {
    throw new HttpError(400, 'invalid_json', 'Request body is not valid JSON');
  }
}

/** An error with an HTTP status, a machine-readable code and a message that is safe to send to clients. */
export class HttpError extends Error {
  readonly status: number;
  readonly code: string;
  readonly headers: Record<string, string>;

  constructor(status: number, code: string, message: string, headers: Record<string, string> = {}) {
    super(message);
    this.name = 'HttpError';
    this.status = status;
    this.code = code;
    this.headers = headers;
  }
}

export interface ErrorResponse {
  status: number;
  body: { error: { code: string; message: string } };
  headers: Record<string, string>;
  /** True for errors that are not HttpError. They are logged, and the client gets no details. */
  unexpected: boolean;
}

/** Maps any thrown value to the JSON error response sent to the client. */
export function toErrorResponse(err: unknown): ErrorResponse {
  if (err instanceof HttpError) {
    return {
      status: err.status,
      body: { error: { code: err.code, message: err.message } },
      headers: err.headers,
      unexpected: false,
    };
  }
  return {
    status: 500,
    body: { error: { code: 'internal_error', message: 'Internal server error' } },
    headers: {},
    unexpected: true,
  };
}

import type { IncomingMessage, ServerResponse } from 'node:http';

/** Structured logger. Every call writes one JSON object; extra fields are merged in. */
export interface Logger {
  debug(msg: string, fields?: Record<string, unknown>): void;
  info(msg: string, fields?: Record<string, unknown>): void;
  warn(msg: string, fields?: Record<string, unknown>): void;
  error(msg: string, fields?: Record<string, unknown>): void;
}

/** Query string values. A key that repeats in the URL becomes an array. */
export type Query = Record<string, string | string[]>;

export interface Context {
  req: IncomingMessage;
  res: ServerResponse;
  /** Decoded path parameters, e.g. `:id`. */
  params: Record<string, string>;
  query: Query;
  /** Parsed JSON body for POST, PUT and PATCH. `undefined` when the body is empty. */
  body: unknown;
  /** Logger bound to this request's `requestId`. */
  log: Logger;
  requestId: string;
}

/** A response with an explicit status and/or headers. Return it from a handler. */
export class Reply {
  readonly status: number;
  readonly body: unknown;
  readonly headers: Record<string, string>;

  constructor(status: number, body?: unknown, headers: Record<string, string> = {}) {
    this.status = status;
    this.body = body;
    this.headers = headers;
  }
}

export function reply(status: number, body?: unknown, headers: Record<string, string> = {}): Reply {
  return new Reply(status, body, headers);
}

/**
 * A handler returns a value, which is sent as JSON with status 200, or a
 * `reply()` for another status. It may instead write the response itself and
 * return `undefined`. `undefined` with nothing written is sent as 204.
 */
export type Handler = (ctx: Context) => unknown;

/** Runs before routing. Call `next()` to continue; return without calling it to end the request. */
export type Middleware = (ctx: Context, next: () => Promise<void>) => void | Promise<void>;

import type { Router } from '../router.js';
import { reply } from '../types.js';

/** GET /health (liveness) and GET /ready (readiness). Neither needs a body or credentials. */
export function registerHealthRoutes(router: Router, isReady: () => boolean): void {
  router.get('/health', () => ({ status: 'ok' }));
  router.get('/ready', () => (isReady() ? { status: 'ready' } : reply(503, { status: 'not_ready' })));
}

import { afterEach, describe, expect, it } from 'vitest';
import { loadConfig, type Config } from '../src/config.js';
import { createLogger } from '../src/logger.js';
import type { Router } from '../src/router.js';
import { createServer, type AppServer } from '../src/server.js';

