describe('graceful shutdown', () => {
  it('lets a slow in-flight request finish, then refuses new connections', async () => {
    let markStarted: () => void = () => undefined;
    const started = new Promise<void>((resolve) => {
      markStarted = resolve;
    });
    const { server, base } = await startServer((router) => {
      router.get('/slow', async () => {
        markStarted();
        await sleep(300);
        return { done: true };
      });
    });

    const inFlight = fetch(`${base}/slow`).then((res) => res.json());
    await started;

    const result = await server.shutdown();
    expect(await inFlight).toEqual({ done: true });
    expect(result).toEqual({ forced: false });
    expect(server.isReady()).toBe(false);
    await expect(fetch(`${base}/health`)).rejects.toThrow();
  });

  it('destroys requests still running after SHUTDOWN_TIMEOUT_MS', async () => {
    let markStarted: () => void = () => undefined;
    const started = new Promise<void>((resolve) => {
      markStarted = resolve;
    });
    const { server, base } = await startServer(
      (router) => {
        router.get('/hang', () => {
          markStarted();
          return new Promise(() => undefined);
        });
      },
      { shutdownTimeoutMs: 100 },
    );

    const hung = fetch(`${base}/hang`).catch((err: unknown) => err);
    await started;

    const startedAt = Date.now();
    const result = await server.shutdown();
    expect(result).toEqual({ forced: true });
    expect(Date.now() - startedAt).toBeLessThan(2000);
    expect(await hung).toBeInstanceOf(Error);
  });

  it('returns the same result when called more than once', async () => {
    const { server } = await startServer(() => undefined, { shutdownTimeoutMs: 100 });
    const first = await server.shutdown();
    const second = await server.shutdown();
    expect(second).toEqual(first);
  });
});

import type { Middleware } from '../types.js';

const ALLOWED_METHODS = 'GET,POST,PUT,PATCH,DELETE,OPTIONS';
const DEFAULT_ALLOWED_HEADERS = 'content-type,x-request-id';
const MAX_AGE_SECONDS = '600';

/**
 * CORS headers on every response. `origin` is CORS_ORIGIN: `*` or one specific
 * origin. Preflight requests (OPTIONS with Access-Control-Request-Method) are
 * answered here, before routing, so they work for any path.
 */
export function createCorsMiddleware(origin: string): Middleware {
  const specificOrigin = origin !== '*';

  return (ctx, next) => {
    const { req, res } = ctx;
    res.setHeader('access-control-allow-origin', origin);
    if (specificOrigin) res.setHeader('vary', 'Origin');

    const isPreflight = req.method === 'OPTIONS' && req.headers['access-control-request-method'] !== undefined;
    if (!isPreflight) return next();

    const requested = req.headers['access-control-request-headers'];
    res.setHeader('access-control-allow-methods', ALLOWED_METHODS);
    res.setHeader(
      'access-control-allow-headers',
      typeof requested === 'string' && requested.length > 0 ? requested : DEFAULT_ALLOWED_HEADERS,
    );
    res.setHeader('access-control-max-age', MAX_AGE_SECONDS);
    res.statusCode = 204;
    res.end();
    return undefined;
  };
}

